INSERT INTO public.manga VALUES (2, 'Lanterns After Rain', 'Two strangers share an umbrella every rainy Tuesday. Neither knows the other''s name.', 2, 'https://picsum.photos/seed/surituk-cover-2/400/560', 'https://picsum.photos/seed/surituk-banner-2/1600/700', 'Romance', '{"slow burn",school}', 'English', 'ongoing', 1760000, 141000, 4, 4.8, true, false, true, false, 2, 2, '2026-10-19 13:43:05.215+00', '2026-11-06 13:43:05.215+00');
